package org.ikigaidigital.config;

import io.swagger.v3.oas.models.OpenAPI;
import io.swagger.v3.oas.models.info.Info;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;

/**
 * Metadata of the OpenAPI contract. The contract itself is generated by springdoc from the web adapter
 * annotations: JSON at {@code /v3/api-docs}, YAML at {@code /v3/api-docs.yaml}, UI at {@code /swagger-ui.html}.
 */
@Configuration(proxyBeanMethods = false)
class OpenApiConfiguration {

    @Bean
    OpenAPI timeDepositOpenApi() {
        return new OpenAPI().info(new Info()
                .title("XA Bank Time Deposit API")
                .version("1.0.0")
                .description("Lists time deposits and applies monthly interest to their balances."));
    }
}
